<script>
  import {locateDocumentNode,tableScopeCells,setTableCells,alignDocumentBlock,setTableRowHeights,setTablePadding,tablePadding} from '../../public/libs/maths-editor/document-operations.mjs';
  import {containerSpacingFields} from '../lib/booklet-direct-layout.js';
  import {equationRowSpacing,setEquationRowSpacing,equationRowGaps,setEquationRowGap} from '../../public/libs/maths-editor/equation-spacing.mjs';
  // `row` and `example` are read on demand: the editor is placed on the page after this panel mounts.
  let {editor,questionLabel='Question',onboundary=()=>{},row=null,onrow=null,example=null,onexample=null,category='layout'}=$props();
  let revision=$state(0),draft=null,problem=$state('');
  let blankSelection=$state.raw(null);
  let scope=$state('cell'),single=$state(false),rowDraft=$state({}),exampleDraft=$state({});
  const c=$derived(editor?.documentController);
  const context=$derived.by(()=>{revision;const at=c&&locateDocumentNode(c.doc,c.selectedId);const ancestors=at?.ancestors??[];const table=[...ancestors,at?.node].findLast(n=>n?.type==='table');const cellEl=c?.surface.querySelector(`[data-id="${CSS.escape(c.selectedId??'')}"]`)?.closest('td,th');const cell=table?.rows.flat().find(n=>n.id===(cellEl?.dataset.id??[...ancestors,at?.node].findLast(n=>n?.type==='cell')?.id))??(at?.node?.type==='table'?table?.rows[0]?.[0]:null);return {node:at?.node,ancestors,table,cell,row:table?.rows.findIndex(r=>r.includes(cell)),math:c?.mathEditing?.field()};});
  const spacing=$derived(context.math?equationRowSpacing(context.math.getValue('latex')):null);
  const enclosingLayouts=$derived([...context.ancestors,context.node].filter(n=>n?.type==='layout'));
  const selectedBlank=$derived.by(()=>{revision;const paragraph=blankSelection&&c&&locateDocumentNode(c.doc,blankSelection.paragraphId)?.node;return paragraph?.id===context.node?.id?paragraph.inlines?.filter(n=>n.type==='cloze')[blankSelection.index]:null;});
  function selectBlank(event){const el=event.composedPath().find(n=>n.matches?.('[data-cloze]'));const paragraph=el?.closest('[data-type="paragraph"]');blankSelection=paragraph?{paragraphId:paragraph.dataset.id,index:[...paragraph.querySelectorAll('[data-cloze]')].indexOf(el)}:null;}
  function changeBlank(property,input){if(input.value===''||!input.validity.valid)return;edit(doc=>{const paragraph=locateDocumentNode(doc,blankSelection.paragraphId)?.node,blank=paragraph?.inlines.filter(n=>n.type==='cloze')[blankSelection.index];if(blank)blank[property]=Number(input.value);});}
  const cellPadding=$derived.by(()=>{if(!context.cell)return null;const values=scoped.flatMap(cell=>['Top','Right','Bottom','Left'].map(side=>cell['padding'+side]??context.table.padding));return values.every(v=>v===values[0])?values[0]:null;});
  const paragraphs=$derived.by(()=>{revision;if(draft?.paragraphIds)return draft.paragraphIds.map(id=>locateDocumentNode(c.doc,id)?.node).filter(Boolean);const range=c?.range;if(range&&!range.collapsed){const nodes=[...c.surface.querySelectorAll('[data-type="paragraph"]')].filter(el=>range.intersectsNode(el)).map(el=>locateDocumentNode(c.doc,el.dataset.id)?.node).filter(Boolean);if(nodes.length)return nodes;}return context.node?.type==='paragraph'?[context.node]:[];});
  const paragraph=$derived(paragraphs[0]);
  const gaps=$derived(context.math?equationRowGaps(context.math.getValue('latex')):[]);
  const scoped=$derived(context.cell?tableScopeCells(context.table,context.cell.id,scope):[]);
  const shared=(key,fallback)=>{const values=scoped.map(cell=>cell[key]??fallback);return values.length&&values.every(v=>v===values[0])?values[0]:null;};
  const rowHeights=$derived(context.table?context.table.rows.map((_,i)=>context.table.rowHeights?.[i]??10):[]);
  const tableRowHeight=$derived(rowHeights.every(v=>v===rowHeights[0])?rowHeights[0]:null);
  const wholeRows=$derived(scope==='column'||scope==='table');
  const positioned=$derived(paragraph??context.ancestors.findLast(n=>n.type==='paragraph'));
  const inCell=$derived(!!positioned&&!!context.cell?.blocks.some(b=>b.id===positioned.id));
  const position=$derived(positioned?(inCell&&!context.cell.preserveParagraphAlignment?context.cell.align:positioned.align)??'left':null);
  const rowInfo=$derived.by(()=>{revision;return row?.()??null;});
  const exampleInfo=$derived.by(()=>{revision;return example?.()??null;});
  // Button-style edits are one committed step; typed fields keep the live preview below.
  function edit(fn){commit();onboundary();c.transact(doc=>{fn(doc);});onboundary();revision++;}
  const setCells=patch=>edit(doc=>setTableCells(doc,context.cell.id,patch,scope));
  const setPosition=value=>edit(doc=>alignDocumentBlock(doc,positioned.id,value,{single:inCell&&single}));
  function setTable(key,value){if(value===''||!Number.isFinite(Number(value)))return;const id=context.table.id;edit(doc=>{locateDocumentNode(doc,id).node[key]=Number(value);});}
  function setSide(side,value){if(value===''||!Number.isFinite(Number(value)))return;setCells({['padding'+side]:Number(value)});}
  const number=(target,key,value)=>{if(value===''||!Number.isFinite(Number(value)))delete target[key];else target[key]=Number(value);};
  function common(property,fallback){const values=paragraphs.map(p=>p[property]??fallback);return values.every(v=>v===values[0])?values[0]:'';}
  $effect(()=>{const host=editor;const update=()=>revision++;for(const name of ['document-selection','document-change','focusin','click','keyup'])host?.addEventListener(name,update);host?.addEventListener('click',selectBlank);return()=>{cancel();host?.removeEventListener('click',selectBlank);for(const name of ['document-selection','document-change','focusin','click','keyup'])host?.removeEventListener(name,update);};});
  function begin(){if(draft)return;onboundary();draft={doc:structuredClone(c.doc),paragraphIds:paragraphs.map(p=>p.id),math:context.math,latex:context.math?.getValue('latex')};}
  // A row height below the 4 mm minimum is a number still being typed; clamping it here would rewrite the field.
  function preview(id,key,value){if(value===''||!Number.isFinite(Number(value)))return;if(['rowHeight','tableRowHeight'].includes(key)&&Number(value)<4)return;begin();const next=structuredClone(draft.doc),at=locateDocumentNode(next,id);if(!at)return;if(key==='rowHeight')setTableRowHeights(at.node,Number(value),wholeRows?null:[context.row]);else if(key==='tableRowHeight')setTableRowHeights(at.node,Number(value));else if(key==='tablePadding')setTablePadding(at.node,Number(value));else if(key==='paddingAll')for(const cell of tableScopeCells(at.parent,id,scope))for(const side of ['Top','Right','Bottom','Left'])cell['padding'+side]=Number(value);else if(['lineHeight','spaceBefore','spaceAfter','indent'].includes(key)&&at.node.type==='paragraph')for(const target of draft.paragraphIds)locateDocumentNode(next,target).node[key]=Number(value);else at.node[key]=Number(value);if(context.cell&&['spaceBefore','spaceAfter'].includes(key))locateDocumentNode(next,context.cell.id).node.preserveParagraphSpacing=true;const focus=document.activeElement;c.doc=next;c.render();focus?.focus({preventScroll:true});revision++;}
  function equation(value){if(value===''||!Number.isFinite(Number(value)))return;begin();try{draft.math.setValue(setEquationRowSpacing(draft.latex,Number(value)),{silenceNotifications:true});c.capture();c.mathEditing.refresh();problem='';revision++;}catch(e){problem=e.message;}}
  function equationLine(index,value){if(value===''||!Number.isFinite(Number(value)))return;begin();try{draft.math.setValue(setEquationRowGap(draft.latex,index,Number(value)),{silenceNotifications:true});c.capture();c.mathEditing.refresh();problem='';revision++;}catch(e){problem=e.message;}}
  function commit(){if(!draft)return;draft=null;c.remember();c.emit();onboundary();revision++;}
  function cancel(){if(!draft)return;const old=draft;draft=null;c.doc=old.doc;if(old.math?.isConnected)old.math.setValue(old.latex,{silenceNotifications:true});c.render();revision++;onboundary();}
  function key(event){if(event.key==='Escape'&&draft){event.preventDefault();event.stopPropagation();cancel();}if(event.key==='Enter'){event.preventDefault();commit();}}
  function target(id){commit();c.select(c.surface.querySelector(`[data-id="${CSS.escape(id)}"]`));revision++;}
  function preset(value){preview(paragraph.id,'lineHeight',value);commit();}
  function latex(){[...editor.querySelectorAll('.me-math-tools button'),...document.querySelectorAll('.document-toolbar .me-math-tools button')].find(b=>b.textContent==='Edit LaTeX')?.click();}
  function advanced(node){node.append(c.inspector);const organise=()=>{const root=c.inspector.querySelector('.me-common-properties')??c.inspector;for(const el of [...root.children]){const label=el.firstChild?.textContent??'';if(el.tagName==='LABEL'&&/^(Before \(mm\)|After \(mm\)|Layout gap \(mm\)|Indent \(mm\)|Line spacing|Space above image|Width \(mm\)|Table margin|Table width|Cell horizontal alignment|Cell vertical alignment|Cell top padding|Cell padding|Row height)/.test(label)){el.hidden=true;continue;}if(/JSON/.test(label)&&el.tagName==='LABEL'){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=/JSON/.test(label)?'Specialist data':label.trim();el.before(details);details.append(summary,el);}}};organise();editor.addEventListener('document-selection',organise);return {destroy(){editor.removeEventListener('document-selection',organise);if(editor.isConnected)editor.append(c.inspector);}};}
</script>

<div class="selection-spacing" data-equation-control role="group" tabindex="-1" aria-label="Selection spacing">
  <nav class="breadcrumb" aria-label="Selection target"><span>{questionLabel}</span>{#each [...context.ancestors,context.node].filter(n=>n?.id&&n.type!=='document') as node}<span aria-hidden="true">›</span><button onclick={()=>target(node.id)}>{node.type==='paragraph'?'Text':node.type==='table'?'Table':node.type==='cell'?'Cell':node.type}</button>{/each}{#if context.math}<span>› Equation</span>{/if}</nav>
  {#if category!=='tables'}
  {#if selectedBlank}<h3>Answer blank</h3><div class="fields"><label>Width (mm)<input aria-label="Answer blank width (mm)" type="number" min="8" max="120" step=".5" value={selectedBlank.width} onchange={e=>changeBlank('width',e.currentTarget)}/></label><label>Writing lines<input aria-label="Answer blank writing lines" type="number" min="1" max="10" step="1" value={selectedBlank.lines??1} onchange={e=>changeBlank('lines',e.currentTarget)}/></label></div>{/if}
  {#if spacing}
    <h3>Equation spacing</h3>
    {#if spacing.supported}
      <label>Between equation lines <span>additional gap (mm)</span><input aria-label="Between equation lines (mm)" type="number" min="0" max="30" step="0.5" placeholder={spacing.mixed?'Mixed':''} value={spacing.valueMm??''} oninput={e=>equation(e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>
      <div class="presets"><button onclick={()=>{equation(Math.max(0,(spacing.valueMm??0)-.5));commit();}}>Tighter</button><button onclick={()=>{equation((spacing.valueMm??0)+.5);commit();}}>Looser</button></div>
      {#if gaps.length>1}<details class="lines"><summary>Each line separately</summary><div class="fields">{#each gaps as gap,index}<label>After line {index+1} (mm)<input aria-label={'Gap after equation line '+(index+1)+' (mm)'} type="number" min="0" max="30" step="0.5" value={gap??''} placeholder={gap==null?'Custom':''} oninput={e=>equationLine(index,e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{/each}</div></details>{/if}
    {:else}<p>This equation has no supported outer row structure. Nested matrices keep their own spacing.</p>{/if}
    <button onclick={latex}>Edit LaTeX</button>
  {/if}
  {#if paragraph}
    <h3>{spacing?'Around the equation':context.cell?'Cell text':'Paragraph'}</h3>
    {#if !spacing}<div class="presets" aria-label="Paragraph spacing presets">{#each [1,1.15,1.5,2] as value}<button aria-pressed={common('lineHeight',1.4)===value} onclick={()=>preset(value)}><span class="preview" style:line-height={value}>━<br/>━</span>{value===1?'Single':value===2?'Double':value}</button>{/each}</div>{/if}
    <div class="fields">{#each (spacing?[['spaceBefore','Space before (mm)',0],['spaceAfter','Space after (mm)',2]]:[['lineHeight','Line spacing',1.4],['spaceBefore','Space before (mm)',0],['spaceAfter','Space after (mm)',2],['indent','Indent (mm)',0]]) as [property,label,fallback]}<label>{label}<input aria-label={label} type="number" min={property==='lineHeight'?1:0} max={property==='lineHeight'?3:300} step={property==='lineHeight'?.05:.5} value={common(property,fallback)} placeholder={common(property,fallback)===''?'Mixed':''} oninput={e=>preview(paragraph.id,property,e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{/each}</div>
  {/if}
  {#if positioned}
    <h3>{context.math?'Equation position':'Position'}</h3>
    <div class="presets" role="group" aria-label="Position on the page">{#each [['left','Left'],['center','Centre'],['right','Right']] as [value,label]}<button aria-pressed={position===value} onclick={()=>setPosition(value)}>{label}</button>{/each}</div>
    {#if inCell&&!context.cell.preserveParagraphAlignment&&context.cell.blocks.length>1}<label class="check"><input type="checkbox" bind:checked={single}/>Only this line (other lines in the cell stay put)</label>{/if}
  {/if}
  {#each enclosingLayouts as layout}
    <h3>Enclosing {layout.arrangement} layout</h3>
    <div class="fields">{#each containerSpacingFields(layout) as [property,label,fallback]}<label>{label}<input aria-label={'Layout '+layout.id+' '+label.toLowerCase()} type="number" min="0" max="20" step=".5" value={layout[property]??fallback} oninput={e=>preview(layout.id,property,e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{/each}</div>
  {/each}
  {#if ['spacer','list'].includes(context.node?.type)}<h3>{context.node.type==='spacer'?'Writing space':'List'}</h3>{#each containerSpacingFields(context.node) as [property,label,fallback,max,min=0]}<label>{label}<input aria-label={label} type="number" {min} {max} step=".5" value={context.node[property]??fallback} oninput={e=>preview(context.node.id,property,e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{/each}{/if}
  {/if}
  {#if category==='tables'&&context.table}
    <h3>This table</h3>
    <div class="fields"><label>All rows height (mm)<input aria-label="All table rows height (mm)" type="number" min="4" max="80" step=".5" value={tableRowHeight??''} placeholder={tableRowHeight==null?'Mixed':''} oninput={e=>preview(context.table.id,'tableRowHeight',e.currentTarget.value)} onkeydown={key} onchange={commit}/></label><label>All cells padding (mm)<input aria-label="All table cells padding (mm)" type="number" min="0" max="20" step=".5" value={tablePadding(context.table)??''} placeholder={tablePadding(context.table)==null?'Mixed':''} oninput={e=>preview(context.table.id,'tablePadding',e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{#each [['marginBefore','Space above (mm)','Space above table (mm)'],['marginAfter','Space below (mm)','Space below table (mm)']] as [property,label,aria]}<label>{label}<input aria-label={aria} type="number" min="0" max="30" step=".5" value={context.table[property]??2} onchange={e=>setTable(property,e.currentTarget.value)}/></label>{/each}</div>
    {#if context.table.annotations?.some(a=>a.type==='arrow'&&['top','bottom'].includes(a.side))}<p class="hint">Table arrows and labels reserve space above or below the table. Adjust their distance and curve in the arrow settings below.</p>{/if}
    <label>Table width (mm)<input aria-label="Table width (mm)" type="number" min="10" max="190" step=".5" value={context.table.widthMm??''} placeholder="Auto" onchange={e=>{if(e.currentTarget.value!==''&&e.currentTarget.validity.valid)setTable('widthMm',e.currentTarget.value);}}/></label><button onclick={()=>edit(doc=>{locateDocumentNode(doc,context.table.id).node.widthMm=null;})}>Auto table width</button>
    {#if context.cell}<h3>This cell</h3>
    <div class="presets scope" role="group" aria-label="Apply cell settings to">{#each [['cell','Cell'],['row','Row'],['column','Column'],['table','Table']] as [value,label]}<button aria-pressed={scope===value} onclick={()=>scope=value}>{label}</button>{/each}</div>
    <div class="align-grid" role="group" aria-label="Cell alignment">{#each ['top','middle','bottom'] as vertical}{#each ['left','center','right'] as horizontal}<button title={vertical+' '+(horizontal==='center'?'centre':horizontal)} aria-label={'Align '+vertical+' '+(horizontal==='center'?'centre':horizontal)} aria-pressed={shared('verticalAlign','middle')===vertical&&shared('align','center')===horizontal} onclick={()=>setCells({align:horizontal,verticalAlign:vertical})}><span style:align-self={{top:'start',middle:'center',bottom:'end'}[vertical]} style:justify-self={{left:'start',center:'center',right:'end'}[horizontal]}></span></button>{/each}{/each}</div>
    <div class="fields"><label>{wholeRows?'Row height (mm)':'This row height (mm)'}<input aria-label="Row minimum height (mm)" type="number" min="4" max="80" step=".5" value={wholeRows?tableRowHeight??'':rowHeights[context.row]??10} placeholder={wholeRows&&tableRowHeight==null?'Mixed':''} oninput={e=>preview(context.table.id,'rowHeight',e.currentTarget.value)} onkeydown={key} onchange={commit}/></label><label>Padding (mm)<input aria-label="Cell padding (mm)" type="number" min="0" max="20" step=".5" value={cellPadding??''} placeholder={cellPadding==null?'Mixed':''} oninput={e=>preview(context.cell.id,'paddingAll',e.currentTarget.value)} onkeydown={key} onchange={commit}/></label></div>
    <h3>Padding on each side</h3><div class="fields">{#each ['Top','Right','Bottom','Left'] as side}<label>{side} (mm)<input aria-label={'Cell '+side.toLowerCase()+' padding (mm)'} type="number" min="0" max="20" step=".5" value={shared('padding'+side,context.table.padding)??''} placeholder="Mixed" onchange={e=>setSide(side,e.currentTarget.value)}/></label>{/each}</div>{/if}
  {/if}
  {#if category!=='tables'}
  {#if rowInfo&&onrow}
    <h3>Side-by-side row</h3><p class="hint">Spacing of the row of boxes this text sits in. Applying closes the text editor.</p>
    <div class="fields">{#each [['gap','Gap between columns (mm)',2],['before','Space above row (mm)',0],['after','Space below row (mm)',0]] as [property,label,fallback]}<label>{label}<input aria-label={label} type="number" min="0" max={property==='gap'?30:80} step=".5" value={rowDraft[property]??rowInfo.node[property]??fallback} oninput={e=>number(rowDraft,property,e.currentTarget.value)}/></label>{/each}</div>
    <button disabled={!Object.keys(rowDraft).length} onclick={()=>{const patch={...rowDraft};rowDraft={};commit();onrow(rowInfo,patch);}}>Apply row spacing</button>
  {/if}
  {#if exampleInfo&&onexample}
    <h3>Worked example row</h3><p class="hint">Applying closes the text editor.</p>
    <div class="fields">{#each [['aboveMm','Space above (mm)',2],['belowMm','Space below (mm)',4],['gapMm','Gap between columns (mm)',3],['minHeightMm','Minimum height (mm)',29]] as [property,label,fallback]}<label>{label}<input aria-label={'Worked example '+label.toLowerCase()} type="number" min="0" max="120" step=".5" value={exampleDraft[property]??exampleInfo.layout[property]??fallback} oninput={e=>number(exampleDraft,property,e.currentTarget.value)}/></label>{/each}</div>
    <button disabled={!Object.keys(exampleDraft).length} onclick={()=>{const patch={...exampleDraft};exampleDraft={};commit();onexample(exampleInfo.id,patch);}}>Apply example spacing</button>
  {/if}
  {#if ['image','inline-image'].includes(context.node?.type)}<h3>Image</h3><div class="fields">{#each (context.node.type==='inline-image'?[['width','Width (mm)',18]]:[['width','Width (mm)',78],['spaceBefore','Space above (mm)',0],['spaceAfter','Space below (mm)',0]]) as [property,label,fallback]}<label>{label}<input aria-label={label} type="number" min="0" step=".5" value={context.node[property]??fallback} oninput={e=>preview(context.node.id,property,e.currentTarget.value)} onkeydown={key} onchange={commit}/></label>{/each}</div>{/if}
  {/if}
  {#if category==='tables'&&!context.table}<p>Select a table or click a table cell for its settings.</p>{/if}
  {#if problem}<p role="alert">{problem}</p>{/if}
  <div hidden={category==='tables'?!context.table:!!context.table}><h3>{category==='tables'?'Columns, borders and structure':'Additional selected-item settings'}</h3><div class="me-document-editor studio-native-properties" use:advanced></div></div>
</div>

<style>
  .selection-spacing{font:14px system-ui;color:inherit}.breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:3px;color:var(--text-muted,#64748b);font-size:12px}.breadcrumb button{border:0;background:transparent;padding:3px;min-height:24px;text-transform:capitalize}h3{font-size:14px;margin:18px 0 8px}p{font-size:13px;line-height:1.5}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}label{display:grid;gap:5px;margin:10px 0;font-size:13px}label span{color:var(--text-muted,#64748b);font-size:12px}input{width:100%;min-width:0;box-sizing:border-box}button,input,summary{font:inherit;color:inherit;border:1px solid var(--line,#cbd5e1);border-radius:5px;background:var(--panel,#fff);padding:6px;min-height:32px}button,summary{cursor:pointer}.presets{display:flex;gap:5px}.presets button{flex:1}.presets button[aria-pressed=true]{outline:2px solid #52769a}.preview{display:block;font-size:10px;color:#52769a;margin:3px}.lines{margin:8px 0}.hint{color:var(--text-muted,#64748b);margin:0 0 6px}.check{display:flex;align-items:center;gap:6px}.check input{width:auto;min-height:0}select{width:100%;font:inherit;color:inherit;border:1px solid var(--line,#cbd5e1);border-radius:5px;background:var(--panel,#fff);padding:6px;min-height:32px}.align-grid{display:grid;grid-template-columns:repeat(3,34px);gap:3px;margin:8px 0}.align-grid button{display:grid;width:34px;height:34px;min-height:0;padding:5px}.align-grid button span{width:10px;height:6px;border-radius:1px;background:#52769a}.align-grid button[aria-pressed=true]{outline:2px solid #52769a}button:disabled{opacity:.45;cursor:default}.studio-native-properties{border:0!important;padding:0!important;background:transparent!important;color:inherit!important;font:inherit!important;min-width:0}.studio-native-properties :global(.me-properties){display:block!important;padding:6px 0!important;background:transparent!important;border:0!important;color:inherit!important}.studio-native-properties :global(.me-common-properties){display:grid!important;gap:8px}.studio-native-properties :global(label){display:grid!important;gap:4px;font-size:13px!important;min-width:0;margin:0!important}.studio-native-properties :global(input),.studio-native-properties :global(select){width:100%;min-width:0;box-sizing:border-box;min-height:32px;background:var(--panel,#fff);color:inherit;border:1px solid var(--line,#cbd5e1)}.studio-native-properties :global(button){max-width:100%;white-space:normal}.studio-native-properties :global(details){min-width:0}.studio-native-properties :global(.me-properties-title){display:none}.studio-native-properties :global([hidden]){display:none!important}
</style>
